(function(E){ const x = E["int-m1"] = E["int-m1"] || {units:{}}; x.units["int-2"] = {"grammar":{"id":"c-int-2-g","level":"B1","course":"interview","unit":"int-2","title":"Short answers that match the question","titleTr":"Soruya uyan kısa cevaplar","titleFa":"جواب کوتاهی که با سؤال جور است","formsTable":{"headers":{"en":["Question starts with","Short answer"],"tr":["Soru şununla başlıyor","Kısa cevap"],"fa":["سؤال با این شروع می‌شود","جواب کوتاه"]},"rows":[["Do you...?","Yes, I do. / No, I don't."],["Have you ever...?","Yes, I have. / No, I haven't."],["Are you...? / Can you...? / Would you...?","Yes, I am. / Yes, I can. / Yes, I would."],["Could you tell me if you...?","Answer the real question: Yes, I do."]]},"wrong":"\"Do you agree to a background check?\" \"Yes, I am agree.\"","right":"\"Do you agree to a background check?\" \"Yes, I do.\"","blank":{"sentence":"\"Do you have the right to work in this country?\" \"No, I ___, but I can get a work visa.\"","word":"don't","distractors":["didn't","am not"]},"wrong2":"\"Are you available from April?\" \"Yes, I do.\"","right2":"\"Are you available from April?\" \"Yes, I am.\"","blank2":{"sentence":"\"Would you be willing to work nights?\" \"Yes, I ___. I work nights now.\"","word":"would","distractors":["do","have"]},"expParts":{"rule":[{"en":"Repeat the question's helper verb. A bare \"Yes\" can sound cold.","tr":"Sorudaki yardımcı fiili tekrar et. Tek başına \"Yes\" soğuk duyulabilir.","fa":"فعل کمکی سؤال را تکرار کن، چون گفتن «Yes» به‌تنهایی ممکن است سرد باشد.","ex":"Do you have a licence? Yes, I do."},{"en":"Then add one detail.","tr":"Sonra bir ayrıntı ekle.","fa":"بعد یک نکته اضافه کن.","ex":"Yes, I do. I've had it since 2016."},{"en":"\"Could you tell me if...?\" is polite: answer the real question.","tr":"\"Could you tell me if...?\" yalnızca kibar bir sorudur; bu yüzden asıl soruyu cevapla.","fa":"جمله‌ی «Could you tell me if...?» فقط شکل مؤدبانه‌ی پرسیدن است؛ پس به خود سؤال جواب بده.","ex":"Could you tell me if you can start in April? Yes, I can."},{"en":"Don't know a word? Ask about it.","tr":"Bir kelimeyi bilmiyor musun? Sor.","fa":"کلمه‌ای را نمی‌دانی؟ بپرس.","ex":"Sorry, what do you mean by notice period?"}],"test":{"en":"Find the real question (after 'if', or after the helper verb). Answer with the same helper verb.","tr":"Asıl soruyu bul ('if'ten sonra ya da yardımcı fiilden sonra). Aynı yardımcı fiille cevap ver.","fa":"سؤال اصلی را پیدا کن (بعد از if یا بعد از فعل کمکی). با همان فعل کمکی جواب بده."},"contrast":{"en":"Turkish and Persian can answer with just 'yes'. English short answers repeat the helper verb: 'Yes, I do.'","tr":"Türkçede 'Evet, var' ya da sadece 'Evet' deriz. İngilizcede kısa cevap sorudaki yardımcı fiili tekrarlar: 'Yes, I do.'","fa":"در فارسی می‌گوییم «بله، دارم» یا فقط «بله». در انگلیسی جواب کوتاه فعل کمکی سؤال را تکرار می‌کند: «Yes, I do.‎»"}},"errorWatch":[{"find":["i am agree","i'm agree","i am not agree","i'm not agree"],"fix":{"en":"agree is a verb: 'I agree', and the short answer is 'Yes, I do'.","tr":"agree bir fiildir: 'I agree' denir; kısa cevap 'Yes, I do' olur.","fa":"کلمه‌ی agree خودش فعل است: «I agree». جواب کوتاهش هم «Yes, I do» است."}},{"find":["thank you for invite","thanks for invite","thank you to invite"],"fix":{"en":"After 'thank you for', use -ing: 'Thank you for inviting me.'","tr":"'thank you for'dan sonra -ing kullan: 'Thank you for inviting me.'","fa":"بعد از «thank you for» شکل ‎-ing بیاور: «Thank you for inviting me.‎»"}}]},"b2":{"id":"c-int-2-b2","level":"B2","track":"B2","course":"interview","unit":"int-2","title":"Polite preferences: would rather, would prefer to","titleTr":"Kibar tercihler: would rather, would prefer to","titleFa":"ترجیح مؤدبانه: would rather و would prefer to","formsTable":{"headers":{"en":["Form","Example"],"tr":["Yapı","Örnek"],"fa":["ساختار","مثال"]},"rows":[["would rather + verb","I'd rather start in April."],["would prefer to + verb","I'd prefer to start in April."],["negative","I'd rather not say yet. / I'd prefer not to say yet."],["salary question","I'd prefer to discuss salary once I know more about the role."]]},"wrong":"I'd rather to talk about salary later.","right":"I'd rather talk about salary later.","blank":{"sentence":"I would prefer ___ my current salary, but I can give you my expected range.","word":"not to share","distractors":["not share","to not sharing"]},"wrong2":"I prefer start in April, if possible.","right2":"I'd prefer to start in April, if possible.","blank2":{"sentence":"I'd rather ___ my notice period before I start with you.","word":"finish","distractors":["to finish","finishing"]},"useIn":{"en":"B2: in your screening answers, use one polite preference with I'd rather or I'd prefer to (for example about the start date or salary).","tr":"B2: ön eleme cevaplarında I'd rather ya da I'd prefer to ile kibar bir tercih kullan (örneğin başlama tarihi ya da maaş hakkında).","fa":"در مسیر B2: در جواب‌های مصاحبه‌ی تلفنی، یک ترجیح مؤدبانه با I'd rather یا I'd prefer to بیاور (مثلاً درباره‌ی تاریخ شروع یا حقوق)."},"exitItem":{"from":"int-2","kind":"blank","prompt":"I'd rather ___ near the office than commute three hours a day.","options":["live","to live","living"],"correct":0,"why":{"en":"live: 'would rather' takes the plain verb. 'To live' and 'living' don't follow would rather.","tr":"live: 'would rather' yalın fiil alır. 'To live' ve 'living' would rather'dan sonra gelmez.","fa":"live درست است، چون بعد از would rather فعل ساده می‌آید. to live و living بعد از would rather نمی‌آیند."}},"expParts":{"rule":[{"en":"would rather + verb, no to.","tr":"would rather + fiil, to yok.","fa":"بعد از would rather فعل ساده می‌آید، بدون to.","ex":"I'd rather start in April."},{"en":"would prefer + to + verb.","tr":"would prefer + to + fiil.","fa":"بعد از would prefer فعل با to می‌آید.","ex":"I'd prefer to start in April."},{"en":"Negative: rather not / prefer not to.","tr":"Olumsuz: rather not / prefer not to.","fa":"در منفی می‌گویی rather not یا prefer not to.","ex":"I'd rather not say yet."},{"en":"Give something back: a range, a date or a reason.","tr":"Karşılığında bir şey ver: bir aralık, bir tarih ya da bir neden.","fa":"به‌جایش چیزی بگو: یک بازه، یک تاریخ یا یک دلیل.","ex":"...but my expected range is 55,000 to 62,000."}],"test":{"en":"After rather: no to. After prefer: to. Say both aloud: 'rather start', 'prefer to start'.","tr":"rather'dan sonra to yok, prefer'den sonra to var. İkisini de yüksek sesle söyle: 'rather start', 'prefer to start'.","fa":"بعد از rather، to نمی‌آید؛ بعد از prefer، to می‌آید. هر دو را بلند بگو: «rather start»، «prefer to start»."},"contrast":{"en":"Turkish 'başlamayı tercih ederim' and Persian 'ترجیح می‌دهم شروع کنم' give no clue about 'to', so learners guess. English: rather + verb, prefer + to + verb.","tr":"Türkçedeki 'başlamayı tercih ederim' to konusunda bir ipucu vermez, bu yüzden tahmin ederiz. İngilizcede: rather + fiil, prefer + to + fiil.","fa":"عبارت فارسی «ترجیح می‌دهم شروع کنم» هیچ سرنخی درباره‌ی to نمی‌دهد و برای همین حدس می‌زنیم. در انگلیسی بعد از rather فعل ساده می‌آید و بعد از prefer فعل با to."}},"errorWatch":[{"find":["rather to"],"fix":{"en":"After would rather, no to: 'I'd rather talk about it later.'","tr":"would rather'dan sonra to gelmez: 'I'd rather talk about it later.'","fa":"بعد از would rather، to نمی‌آید: «I'd rather talk about it later.‎»"}},{"find":["i prefer start","would prefer start","i'd prefer start","prefer not say","prefer not share"],"fix":{"en":"prefer + to + verb: 'I'd prefer to start in April.' Negative: 'I'd prefer not to say.'","tr":"prefer + to + fiil: 'I'd prefer to start in April.' Olumsuz: 'I'd prefer not to say.'","fa":"بعد از prefer فعل با to می‌آید: «I'd prefer to start in April.‎» شکل منفی‌اش این است: «I'd prefer not to say.‎»"}}]},"vocab":{"id":"c-int-2-v","level":"B1","category":"vocab","course":"interview","unit":"int-2","goals":["career"],"title":{"en":"On the Phone with HR","tr":"İK ile Telefonda","fa":"پشت تلفن با منابع انسانی"},"cards":[{"word":"notice period","sentence":"My notice period is four weeks, so I can start in April.","meaning":{"en":"The time you still work after you say you are leaving.","tr":"ihbar süresi.","fa":"مدت پیش‌آگهی استعفا (مدتی که بعد از اعلام استعفا هنوز باید کار کنی)"}},{"word":"available","sentence":"I'm available for an interview any morning this week.","meaning":{"en":"Free to meet or to start.","tr":"müsait.","fa":"در دسترس؛ آزاد برای جلسه یا شروع کار"}},{"word":"expected salary","sentence":"What is your expected salary for this role?","meaning":{"en":"The pay you hope to get in a new job.","tr":"beklenen maaş.","fa":"حقوق درخواستی؛ حقوقی که انتظار داری"}},{"word":"relocate","sentence":"I'm happy to relocate for the right job.","meaning":{"en":"To move to another city or country for work.","tr":"(iş için) başka bir şehre ya da ülkeye taşınmak.","fa":"برای کار به شهر یا کشور دیگری رفتن"}},{"word":"shortlist","sentence":"You are on our shortlist for the second round.","meaning":{"en":"The small group of candidates chosen for the next step.","tr":"kısa liste, son elemeye kalanlar.","fa":"فهرست منتخب؛ متقاضی‌هایی که به مرحله‌ی بعد رفته‌اند"}},{"word":"invitation","sentence":"The invitation says the interview will take forty minutes.","meaning":{"en":"A message that asks you to come somewhere.","tr":"davet.","fa":"دعوت‌نامه"}},{"word":"confirm","sentence":"Could you confirm the time of the interview?","meaning":{"en":"To say that something is true or will happen.","tr":"teyit etmek, onaylamak.","fa":"تأیید کردن"}},{"word":"what do you mean by","sentence":"Sorry, what do you mean by \"probation\"?","meaning":{"en":"A polite way to ask about a word you do not understand.","tr":"Anlamadığın bir kelimeyi kibarca sormanın yolu: \"... ile ne demek istiyorsunuz?\"","fa":"روشی مؤدبانه برای پرسیدن معنی کلمه‌ای که نمی‌فهمی: «منظورتان از ... چیست؟»"}},{"word":"a good time","sentence":"Is this a good time to talk?","meaning":{"en":"A moment when someone is free to talk.","tr":"uygun bir zaman.","fa":"زمان مناسب"}},{"word":"full-time","sentence":"The position is full-time, five days a week.","meaning":{"en":"Working all the normal hours of a working week.","tr":"tam zamanlı.","fa":"تمام‌وقت"}}]},"judge":{"id":"c-int-2-j","course":"interview","unit":"int-2","type":"judge","title":{"en":"Answer, detail, stop","tr":"Cevap, ayrıntı, dur","fa":"جواب، یک نکته، تمام"},"prompt":"Five answers from screening calls. Each one starts with the recruiter's question.","parts":["Answers the question","Adds one useful detail","Short and clear"],"instruction":{"en":"Tap what each answer does. The strongest answer does all three.","tr":"Her cevabın ne yaptığına dokun. En güçlü cevap üçünü de yapar.","fa":"روی کاری که هر جواب می‌کند بزن. قوی‌ترین جواب هر سه را انجام می‌دهد."},"items":[{"by":"Engineer","answer":"\"What notice period do you have?\" My manager is very difficult about these things and my contract is old, so I'll have to look.","present":[],"fix":{"en":"No answer, and a complaint nobody asked for. Check your contract before you apply, then say: \"Four weeks, so I could start on 3 March.\"","tr":"Cevap yok, üstelik kimsenin sormadığı bir şikâyet var. Başvurmadan önce sözleşmene bak, sonra şöyle de: \"Four weeks, so I could start on 3 March.\"","fa":"این جواب نیست و شکایتی هم در آن هست که کسی نپرسیده. قبل از درخواست دادن قراردادت را نگاه کن و بعد بگو: «Four weeks, so I could start on 3 March.»"}},{"by":"Graduate","answer":"\"Do you have a driving licence?\" Yes.","present":["Answers the question","Short and clear"],"fix":{"en":"True, but a little cold on the phone. Use the helper verb and add one detail: \"Yes, I do. I've had it since 2022.\"","tr":"Doğru, ama telefonda biraz soğuk duruyor. Yardımcı fiili kullan ve bir ayrıntı ekle: \"Yes, I do. I've had it since 2022.\"","fa":"درست است، ولی پشت تلفن کمی سرد است. فعل کمکی را بیاور و یک نکته اضافه کن: «Yes, I do. I've had it since 2022.»"}},{"by":"AI tool","answer":"\"Why are you interested in this role?\" I am deeply passionate about leveraging my skills in a dynamic environment, and this exciting opportunity aligns perfectly with my long-term aspirations.","present":[],"fix":{"en":"It says nothing about this job, and the recruiter has nothing to write down. Name one real thing: \"You support clients abroad, and I do that every day.\"","tr":"Bu işle ilgili hiçbir şey söylemiyor ve işe alım uzmanının not alacağı bir şey yok. Gerçek bir şey söyle: \"You support clients abroad, and I do that every day.\"","fa":"این جواب چیزی درباره‌ی این کار نمی‌گوید و کارشناس استخدام هم چیزی برای یادداشت کردن پیدا نمی‌کند. یک چیز واقعی بگو: «You support clients abroad, and I do that every day.»"}},{"by":"Sales assistant","answer":"\"Why do you want to leave your current job?\" They pay late, the manager shouts at everybody, and honestly the whole place is a mess. I could tell you many stories.","present":["Answers the question"],"fix":{"en":"It answers, but blame makes you look risky. Say what you want next: \"I'm looking for a bigger team and more responsibility.\"","tr":"Cevap veriyor, ama suçlamak seni riskli gösterir. Bundan sonra ne istediğini söyle: \"I'm looking for a bigger team and more responsibility.\"","fa":"جواب می‌دهد، ولی وقتی دیگران را مقصر می‌دانی، استخدام کردنت پرریسک به نظر می‌آید. بگو بعد از این چه می‌خواهی: «I'm looking for a bigger team and more responsibility.»"}},{"by":"Good model","answer":"\"What is your expected salary?\" I'm looking for 55,000 to 62,000 lira a month, depending on the full package. Could you tell me the range for this role?","present":["Answers the question","Adds one useful detail","Short and clear"],"fix":null}]},"speaking":{"id":"int-2","course":"interview","unit":"int-2","topic":{"en":"Answering a screening call","tr":"Ön eleme görüşmesinde cevap vermek","fa":"جواب دادن به مصاحبه‌ی تلفنی"},"warmup":{"en":"Imagine your phone rings now. A recruiter asks: \"Is this a good time?\" Say your first sentence.","tr":"Telefonunun şimdi çaldığını düşün. Bir işe alım uzmanı soruyor: \"Is this a good time?\" İlk cümleni söyle.","fa":"تصور کن همین حالا تلفنت زنگ می‌زند. یک کارشناس استخدام می‌پرسد: «Is this a good time?‎» جمله‌ی اولت را بگو."},"questions":[{"en":"Answer: \"Could you tell me why you are interested in this role?\" Give a reason about the job, not only about the city.","tr":"Cevapla: \"Could you tell me why you are interested in this role?\" Sadece şehirle değil, işle ilgili bir neden ver.","fa":"جواب بده: «Could you tell me why you are interested in this role?‎» دلیلی درباره‌ی خود کار بیاور، نه فقط درباره‌ی شهر."},{"en":"Answer: \"Why do you want to leave your current job?\" Say what you want next, not what you dislike now.","tr":"Cevapla: \"Why do you want to leave your current job?\" Şu an neyi sevmediğini değil, bundan sonra ne istediğini söyle.","fa":"جواب بده: «Why do you want to leave your current job?‎» بگو بعد از این چه می‌خواهی، نه اینکه الان از چه چیزی خوشت نمی‌آید."},{"en":"Answer: \"What notice period do you have?\" Give the time and the first date you could start.","tr":"Cevapla: \"What notice period do you have?\" Süreyi ve başlayabileceğin ilk tarihi söyle.","fa":"جواب بده: «What notice period do you have?‎» مدت و اولین تاریخی را که می‌توانی شروع کنی بگو."},{"en":"Answer: \"Do you have the right to work in this country?\" Use a short answer with the helper verb, then one detail.","tr":"Cevapla: \"Do you have the right to work in this country?\" Yardımcı fiilli kısa bir cevap ver, sonra bir ayrıntı ekle.","fa":"جواب بده: «Do you have the right to work in this country?‎» یک جواب کوتاه با فعل کمکی بده و بعد یک نکته."},{"en":"Answer: \"What is your expected salary?\" Give a range, or say politely that you would like to know more about the role first.","tr":"Cevapla: \"What is your expected salary?\" Bir aralık ver ya da önce pozisyon hakkında daha fazla bilgi almak istediğini kibarca söyle.","fa":"جواب بده: «What is your expected salary?‎» یک بازه بگو، یا مؤدبانه بگو که اول می‌خواهی درباره‌ی این شغل بیشتر بدانی."}],"followups":[{"en":"Say all five answers again in 60 seconds, then in 45: short answer, one detail, stop.","tr":"Beş cevabın hepsini önce 60, sonra 45 saniyede tekrar söyle: kısa cevap, bir ayrıntı, dur.","fa":"هر پنج جواب را دوباره بگو، اول در ۶۰ و بعد در ۴۵ ثانیه: جواب کوتاه، یک نکته، تمام."},{"en":"Say 13 and 30, then 15 and 50, so that nobody can mix them up: thirTEEN, THIRty. Then give your start date and salary range again.","tr":"13 ve 30, sonra 15 ve 50 sayılarını kimse karıştırmayacak şekilde söyle: thirTEEN, THIRty. Sonra başlama tarihini ve maaş aralığını yeniden söyle.","fa":"۱۳ و ۳۰، بعد ۱۵ و ۵۰ را طوری بگو که کسی اشتباه نگیرد: thirTEEN، THIRty. بعد تاریخ شروع و بازه‌ی حقوقت را دوباره بگو."}],"expressions":[{"phrase":"Yes, I do. / Yes, I am.","meaning":{"en":"A short answer that matches the question.","tr":"Soruya uyan kısa cevap.","fa":"جواب کوتاهی که با سؤال جور است."}},{"phrase":"Sorry, what do you mean by...?","meaning":{"en":"Asks about a word you do not know.","tr":"Bilmediğin bir kelimeyi sorar.","fa":"معنی کلمه‌ای را که نمی‌دانی می‌پرسد."}},{"phrase":"So I could start on...","meaning":{"en":"Turns your notice period into a date.","tr":"İhbar süreni bir tarihe çevirir.","fa":"مدت پیش‌آگهی‌ات را به یک تاریخ تبدیل می‌کند."}}],"selfCheck":[{"en":"I answered yes/no questions with the helper verb: \"Yes, I do\", \"Yes, I am\".","tr":"Evet/hayır sorularını yardımcı fiille cevapladım: \"Yes, I do\", \"Yes, I am\".","fa":"به سؤال‌های بله/خیر با فعل کمکی جواب دادم: «Yes, I do»، «Yes, I am»."},{"en":"I added one detail after each short answer.","tr":"Her kısa cevaptan sonra bir ayrıntı ekledim.","fa":"بعد از هر جواب کوتاه یک نکته اضافه کردم."},{"en":"I gave my notice period and a real start date.","tr":"İhbar süremi ve gerçek bir başlama tarihi verdim.","fa":"مدت پیش‌آگهی‌ام و یک تاریخ شروع واقعی را گفتم."},{"en":"I did not say anything bad about my current manager.","tr":"Şu anki yöneticim hakkında kötü bir şey söylemedim.","fa":"درباره‌ی مدیر فعلی‌ام هیچ حرف بدی نزدم."}],"model":"Yes, it's a good time, thank you. I'm interested because your team supports clients abroad, and that's what I do every day. I'd like more responsibility in a bigger team. My notice period is four weeks, so I could start on the first of April. Yes, I do have the right to work here. And I'm looking for 55,000 to 62,000 a month."},"writing":{"id":"c-int-2-w","course":"interview","unit":"int-2","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Confirming the interview","tr":"Mülakatı teyit etmek","fa":"تأیید مصاحبه"},"portfolio":null,"prompt":{"en":"A company has invited you to an interview next Thursday at 10:00 at its office. Write a reply (50-80 words): thank them, confirm the day and time, ask one practical question (where to go or what to bring) and close politely. Use the job you want. No job in mind? Use a support job at a travel company.","tr":"Bir şirket seni önümüzdeki perşembe saat 10.00'da ofisinde mülakata çağırdı. Bir cevap yaz (50-80 kelime): teşekkür et, günü ve saati teyit et, pratik bir soru sor (nereye gideceğin ya da ne getireceğin) ve kibarca bitir. İstediğin işi kullan. Aklında bir iş yoksa bir seyahat şirketinde müşteri destek işini kullan.","fa":"یک شرکت تو را برای پنجشنبه‌ی آینده ساعت ۱۰ به مصاحبه در دفترش دعوت کرده است. یک جواب بنویس (۵۰ تا ۸۰ کلمه): تشکر کن، روز و ساعت را تأیید کن، یک سؤال عملی بپرس (کجا بروی یا چه چیزی بیاوری) و مؤدبانه تمام کن. شغلی را که می‌خواهی در نظر بگیر. کار خاصی در نظر نداری؟ یک شغل پشتیبانی در یک شرکت سفر را در نظر بگیر."},"model":"Dear Ms Demir,\n\nThank you for inviting me to an interview for the sales coordinator position. I can confirm that I will be at your office on Thursday at 10:00. Could you tell me if I need to bring any documents?\n\nI look forward to meeting you.\n\nKind regards,\nYour name","frame":"Dear ___,\n\nThank you for inviting me to ___. I can confirm that ___ on ___ at ___. Could you tell me ___?\n\nI look forward to ___.\n\nKind regards,\n___","words":[{"word":"confirm"},{"word":"look forward"}],"minWords":50,"minSentences":4,"rubric":["Task done: thanks, day and time confirmed, one practical question, a close","Organised: thanks first, then the confirmation, then the question, then the close","Language: \"thank you for\" + -ing; a polite question with \"Could you tell me if\"","Tone: polite and short, like a reply from a professional"],"rubricI18n":{"tr":["Görev: teşekkür, gün ve saatin teyidi, bir pratik soru, bir kapanış","Düzen: önce teşekkür, sonra teyit, sonra soru, sonra kapanış","Dil: \"thank you for\" + -ing; \"Could you tell me if\" ile kibar bir soru","Üslup: kibar ve kısa, bir profesyonelin cevabı gibi"],"fa":["کامل بودن کار: تشکر، تأیید روز و ساعت، یک سؤال کاربردی، جمله‌ی پایانی","نظم: اول تشکر، بعد تأیید، بعد سؤال، بعد پایان","زبان: فعل با ing بعد از «thank you for»؛ یک سؤال مؤدبانه با «Could you tell me if»","لحن: مؤدب و کوتاه، مثل جواب یک آدم حرفه‌ای"]}},"exit":{"id":"c-int-2-x","course":"interview","unit":"int-2","type":"exit","items":[{"from":"int-2","kind":"blank","prompt":"\"Do you speak Arabic?\" \"No, I ___, but I am learning.\"","options":["don't","am not","haven't"],"correct":0,"point":2,"why":{"en":"don't: 'Do you speak...?' is answered with do or don't. 'Am not' answers a be question, and 'haven't' answers a have question.","tr":"don't: 'Do you speak...?' sorusu do ya da don't ile cevaplanır. 'Am not' be sorusuna, 'haven't' have sorusuna cevaptır.","fa":"don't درست است، چون جواب کوتاه Do you speak با do یا don't است. am not جواب سؤال be است و haven't جواب سؤال have."}},{"from":"int-2","kind":"blank","prompt":"\"Can you drive a forklift?\" \"Yes, I ___. I have a certificate.\"","options":["do","can","am"],"correct":1,"point":2,"why":{"en":"can: a 'Can you...?' question takes 'can' in the short answer. 'Do' and 'am' answer other questions.","tr":"can: 'Can you...?' sorusunun kısa cevabı 'can' ile verilir. 'Do' ve 'am' başka soruların cevabıdır.","fa":"can درست است، چون جواب کوتاه Can you هم با can است. do و am جواب سؤال‌های دیگرند."}},{"from":"int-2","kind":"mcq","prompt":"The recruiter asks: \"What notice period do you have?\" What does she want to know?","options":["How often your boss is allowed to send you messages","How many days off you have left in your contract this year","How long you must keep working at your job after you resign"],"correct":2,"point":1,"why":{"en":"How long you must keep working after you resign: that is your notice period, and the start date depends on it. Messages and days off are other things.","tr":"İstifadan sonra ne kadar çalışmaya devam etmen gerektiği: bu ihbar sürendir ve başlama tarihi buna bağlıdır. Mesajlar ve izin günleri başka konulardır.","fa":"مدتی که بعد از استعفا باید سر کار بمانی؛ این همان مدت پیش‌آگهی است و تاریخ شروع به آن بستگی دارد. پیام‌ها و روزهای مرخصی چیزهای دیگری‌اند."}},{"from":"int-1","kind":"blank","prompt":"My sister ___ for an online shop since 2023.","options":["writes","has written","wrote"],"correct":1,"point":2,"why":{"en":"has written: 'since 2023' runs until now, so use the present perfect. 'Writes' and 'wrote' can't go with since.","tr":"has written: 'since 2023' bugüne kadar sürer, bu yüzden present perfect. 'Writes' ve 'wrote' since ile kullanılmaz.","fa":"has written درست است، چون since 2023 تا الان ادامه دارد و حال کامل می‌خواهد. writes و wrote با since نمی‌آیند."}},{"from":"int-1","kind":"mcq","prompt":"Which sentence belongs in the \"before\" part of an introduction?","options":["Before this job, I spent three years in a call centre.","I want to work for a company like yours in the near future.","I am a calm person, and people say I listen well."],"correct":0,"point":1,"why":{"en":"'Before this job, I spent three years in a call centre' is past experience. The other two are your future plans and your personality.","tr":"'Before this job, I spent three years in a call centre' geçmiş deneyimdir. Diğer ikisi gelecek planların ve kişiliğinle ilgilidir.","fa":"«Before this job, I spent three years in a call centre» تجربه‌ی گذشته است. دو جمله‌ی دیگر درباره‌ی برنامه‌ی آینده و شخصیت تو هستند."}},{"from":"int-10","kind":"mcq","prompt":"Which line belongs on an English CV?","options":["Cut delivery times by 15% in 2024.","Date of birth: 12 May 1994","Hard-working, honest team player"],"correct":0,"point":1,"why":{"en":"'Cut delivery times by 15% in 2024' is an action with a result. For jobs in English, leave out your date of birth, and 'hard-working' proves nothing.","tr":"'Cut delivery times by 15% in 2024' sonucu olan bir eylemdir. İngilizce işler için doğum tarihini yazma; 'hard-working' de hiçbir şey kanıtlamaz.","fa":"«Cut delivery times by 15% in 2024» کاری است با نتیجه. برای کار به انگلیسی تاریخ تولد را ننویس و hard-working هم چیزی را ثابت نمی‌کند."}}]},"explain":{"id":"c-int-2-e","course":"interview","unit":"int-2","type":"explain","level":"B1","title":{"en":"The screening call","tr":"Ön eleme görüşmesi","fa":"مصاحبه‌ی تلفنی اولیه"},"objective":{"en":"After this lesson, you can answer a screening call clearly and check dates, numbers and words you don't know.","tr":"Bu dersin sonunda bir ön eleme görüşmesini net cevaplayabilecek ve tarihleri, sayıları, bilmediğin kelimeleri teyit edebileceksin.","fa":"بعد از این درس می‌توانی به سؤال‌های مصاحبه‌ی تلفنی اولیه روشن جواب بدهی و تاریخ‌ها، عددها و کلمه‌های ناآشنا را بپرسی تا مطمئن شوی."},"hook":{"en":"A screening call is a short first check: can you do the job, when, and at what pay? The recruiter uses it to choose who gets an interview, so answer short and clearly, from one prepared sheet.","tr":"Ön eleme görüşmesi kısa bir ilk kontroldür: İşi yapabilir misin, ne zaman, hangi ücretle? İşe alım uzmanı mülakata kimin çağrılacağını bu görüşmeyle seçer; bu yüzden hazırladığın tek sayfadan kısa ve net cevap ver.","fa":"مصاحبه‌ی تلفنی اولیه یک بررسی کوتاه است: می‌توانی این کار را انجام بدهی؟ از چه زمانی؟ با چه حقوقی؟ کارشناس استخدام با همین تماس انتخاب می‌کند چه کسی به مصاحبه دعوت شود؛ پس از روی یک برگه‌ی آماده، کوتاه و روشن جواب بده."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Prepare one sheet, then answer short","tr":"Tek sayfa hazırla, sonra kısa cevapla","fa":"یک برگه آماده کن و بعد کوتاه جواب بده"},"steps":[{"en":"The recruiter checks the basics with every candidate, so expect the same few questions.","tr":"İşe alım uzmanı temel bilgileri her adayla kontrol etmek zorundadır; bu yüzden aynı birkaç soruyu bekle.","fa":"کارشناس استخدام باید موارد پایه را با همه‌ی متقاضی‌ها بررسی کند؛ پس منتظر همان چند سؤال باش.","ex":"Legal right to work, notice period, salary range"},{"en":"Keep your numbers and dates on one sheet by your phone, so you don't guess.","tr":"Sayılarını ve tarihlerini tek sayfaya yazıp telefonunun yanında tut. Böylece stres altında tahmin yürütmezsin.","fa":"عددها و تاریخ‌هایت را روی یک برگه بنویس و کنار تلفن بگذار تا زیر فشار حدس نزنی.","ex":"Four weeks' notice. Start 3 March. 55,000-62,000."},{"en":"Answer, add one detail, then stop. Recruiters take notes, and long answers hide the facts.","tr":"Cevapla, bir ayrıntı ekle, sonra dur. İşe alım uzmanı not alır; uzun cevaplar aradığı bilgiyi gizler.","fa":"جواب بده، یک نکته اضافه کن و همان‌جا تمام کن. کارشناس استخدام یادداشت برمی‌دارد و در جواب طولانی، چیزی که لازم دارد گم می‌شود.","ex":"Yes, I do. I've had it since 2022."},{"en":"Repeat numbers back, and ask about any word you miss. A wrong date costs more.","tr":"Sayıları tekrar et ve kaçırdığın her kelimeyi sor. Yanlış bir tarih, bir sorudan çok daha pahalıya gelir.","fa":"عددها را تکرار کن و هر کلمه‌ای را که متوجه نشدی بپرس. یک تاریخ اشتباه خیلی گران‌تر از یک سؤال تمام می‌شود.","ex":"So that's Thursday the 13th at 10:00?"}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Short answers that match the question","tr":"Soruya uyan kısa cevaplar","fa":"جواب کوتاهی که با سؤال جور است"},"steps":[{"en":"Repeat the question's helper verb. A bare \"Yes\" can sound cold.","tr":"Sorudaki yardımcı fiili tekrar et. Tek başına \"Yes\" soğuk duyulabilir.","fa":"فعل کمکی سؤال را تکرار کن، چون گفتن «Yes» به‌تنهایی ممکن است سرد باشد.","ex":"Do you have a licence? Yes, I do."},{"en":"Then add one detail.","tr":"Sonra bir ayrıntı ekle.","fa":"بعد یک نکته اضافه کن.","ex":"Yes, I do. I've had it since 2016."},{"en":"\"Could you tell me if...?\" is polite: answer the real question.","tr":"\"Could you tell me if...?\" yalnızca kibar bir sorudur; bu yüzden asıl soruyu cevapla.","fa":"جمله‌ی «Could you tell me if...?» فقط شکل مؤدبانه‌ی پرسیدن است؛ پس به خود سؤال جواب بده.","ex":"Could you tell me if you can start in April? Yes, I can."},{"en":"Don't know a word? Ask about it.","tr":"Bir kelimeyi bilmiyor musun? Sor.","fa":"کلمه‌ای را نمی‌دانی؟ بپرس.","ex":"Sorry, what do you mean by notice period?"}],"table":{"headers":{"en":["Question starts with","Short answer"],"tr":["Soru şununla başlıyor","Kısa cevap"],"fa":["سؤال با این شروع می‌شود","جواب کوتاه"]},"rows":[["Do you...?","Yes, I do. / No, I don't."],["Have you ever...?","Yes, I have. / No, I haven't."],["Are you...? / Can you...? / Would you...?","Yes, I am. / Yes, I can. / Yes, I would."],["Could you tell me if you...?","Answer the real question: Yes, I do."]]},"tip":{"en":"Turkish and Persian can answer with just 'yes'. English short answers repeat the helper verb: 'Yes, I do.'","tr":"Türkçede 'Evet, var' ya da sadece 'Evet' deriz. İngilizcede kısa cevap sorudaki yardımcı fiili tekrarlar: 'Yes, I do.'","fa":"در فارسی می‌گوییم «بله، دارم» یا فقط «بله». در انگلیسی جواب کوتاه فعل کمکی سؤال را تکرار می‌کند: «Yes, I do.‎»"},"wrong":"Do you have a driving licence? - I like driving very much.","right":"Do you have a driving licence? - Yes, I do. Since 2015."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"If the call comes at a bad time","tr":"Arama kötü bir anda gelirse","fa":"اگر تماس در زمان بدی بود"},"body":{"en":"You don't have to answer on a noisy street. Offer a time: \"I'm at work now. Can I call you back at six?\" Then open your sheet somewhere quiet.","tr":"Gürültülü bir sokakta cevap vermek zorunda değilsin. Bunu söyle ve bir saat öner: \"I'm at work now. Can I call you back at six?\" Sonra sessiz bir yer bul ve sayfanı aç.","fa":"مجبور نیستی وسط خیابان شلوغ جواب بدهی. همین را بگو و یک ساعت پیشنهاد کن: «I'm at work now. Can I call you back at six?» بعد جای ساکتی پیدا کن و برگه‌ات را باز کن."},"phrases":[{"phrase":"Yes, I do. / Yes, I am.","meaning":{"en":"A short answer that matches the question.","tr":"Soruya uyan kısa cevap.","fa":"جواب کوتاهی که با سؤال جور است."}},{"phrase":"Sorry, what do you mean by...?","meaning":{"en":"Asks about a word you do not know.","tr":"Bilmediğin bir kelimeyi sorar.","fa":"معنی کلمه‌ای را که نمی‌دانی می‌پرسد."}},{"phrase":"So I could start on...","meaning":{"en":"Turns your notice period into a date.","tr":"İhbar süreni bir tarihe çevirir.","fa":"مدت پیش‌آگهی‌ات را به یک تاریخ تبدیل می‌کند."}},{"phrase":"notice period","meaning":{"en":"The time you still work after you say you are leaving.","tr":"ihbar süresi.","fa":"مدت پیش‌آگهی استعفا (مدتی که بعد از اعلام استعفا هنوز باید کار کنی)"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Answer the salary question","tr":"Maaş sorusunu cevapla","fa":"به سؤال حقوق جواب بده"},"item":"Weak: Hmm, I don't know, what do you pay? It depends. More than now, because life is expensive. Your facts: you checked pay for this job: 55,000 to 62,000 a month.","answer":"I'm looking for 55,000 to 62,000 a month, depending on the full package. What range do you have for this role?","walk":[{"en":"Check pay for this job first and choose a range, so you don't guess.","tr":"Görüşmeden önce bu işin ücretine bak ve bir aralık seç; böylece tahmin etmek zorunda kalmazsın.","fa":"قبل از تماس حقوق این کار را بررسی کن و یک بازه انتخاب کن تا مجبور نباشی حدس بزنی."},{"en":"Say the range and \"the full package\" (pay plus benefits). Private costs are not their concern.","tr":"Aralığı ve \"the full package\" (maaş ve yan haklar) ifadesini söyle. Özel masrafların onları ilgilendirmez.","fa":"بازه و «the full package» (حقوق به‌علاوه‌ی مزایا) را بگو. هزینه‌های شخصی‌ات به آن‌ها مربوط نیست."},{"en":"End by asking for their range, to see if you are close.","tr":"Yakın olup olmadığınızı görmek için onların aralığını sorarak bitir.","fa":"با پرسیدن بازه‌ی خودشان تمام کن تا ببینی عددهایتان به هم نزدیک است یا نه."}]},"quick":{"prompt":"You missed a word. Say: \"Sorry, what do you ___ by probation?\"","options":["mean","say","think"],"correct":0,"why":{"en":"mean: \"what do you mean by...?\" is the fixed phrase, and recruiters are happy to explain.","tr":"mean: \"what do you mean by...?\" kalıp bir ifadedir ve işe alım uzmanları seve seve açıklar.","fa":"جواب mean است، چون عبارت ثابت what do you mean by...? است. از پرسیدنش هم نترس: کارشناس‌های استخدام با کمال میل توضیح می‌دهند."}},"remember":{"en":"Answer, one detail, stop. Then repeat the numbers back. You can now answer a recruiter's basic questions clearly and check dates and words. Next, you practise a call and reply to an invitation.","tr":"Cevap, bir ayrıntı, dur. Sonra sayıları tekrar et. Artık işe alım uzmanının temel sorularını net cevaplayabilir, tarihleri ve kelimeleri teyit edebilirsin. Sırada bir görüşme alıştırması ve bir davete cevap yazmak var.","fa":"جواب را بگو، یک نکته اضافه کن و همان‌جا تمام کن. بعد عددها را تکرار کن. حالا می‌توانی به سؤال‌های پایه‌ی کارشناس استخدام روشن جواب بدهی و تاریخ‌ها و کلمه‌ها را بپرسی. در ادامه یک تماس را تمرین می‌کنی و به یک دعوت‌نامه جواب می‌دهی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Polite preferences: would rather, would prefer to","tr":"Kibar tercihler: would rather, would prefer to","fa":"ترجیح مؤدبانه: would rather و would prefer to"},"steps":[{"en":"would rather + verb, no to.","tr":"would rather + fiil, to yok.","fa":"بعد از would rather فعل ساده می‌آید، بدون to.","ex":"I'd rather start in April."},{"en":"would prefer + to + verb.","tr":"would prefer + to + fiil.","fa":"بعد از would prefer فعل با to می‌آید.","ex":"I'd prefer to start in April."},{"en":"Negative: rather not / prefer not to.","tr":"Olumsuz: rather not / prefer not to.","fa":"در منفی می‌گویی rather not یا prefer not to.","ex":"I'd rather not say yet."},{"en":"Give something back: a range, a date or a reason.","tr":"Karşılığında bir şey ver: bir aralık, bir tarih ya da bir neden.","fa":"به‌جایش چیزی بگو: یک بازه، یک تاریخ یا یک دلیل.","ex":"...but my expected range is 55,000 to 62,000."}],"table":{"headers":{"en":["Form","Example"],"tr":["Yapı","Örnek"],"fa":["ساختار","مثال"]},"rows":[["would rather + verb","I'd rather start in April."],["would prefer to + verb","I'd prefer to start in April."],["negative","I'd rather not say yet. / I'd prefer not to say yet."],["salary question","I'd prefer to discuss salary once I know more about the role."]]},"body":{"en":"B2: in your screening answers, use one polite preference with I'd rather or I'd prefer to (for example about the start date or salary).","tr":"B2: ön eleme cevaplarında I'd rather ya da I'd prefer to ile kibar bir tercih kullan (örneğin başlama tarihi ya da maaş hakkında).","fa":"در مسیر B2: در جواب‌های مصاحبه‌ی تلفنی، یک ترجیح مؤدبانه با I'd rather یا I'd prefer to بیاور (مثلاً درباره‌ی تاریخ شروع یا حقوق)."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
